/* DropLab — fully client-side skin RNG simulator. No backend, APIs, or account system. */
(() => {
  'use strict';

  const DATA = window.GAME_DATA;
  const STORAGE_KEY = 'droplab-save-v1';
  const DB_NAME = 'droplab-local-db';
  const DB_STORE = 'game';
  const ROLL_COST = 5;
  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];

  const PAGE_NAMES = {
    dashboard: 'ROLL', inventory: 'INVENTORY', equipment: 'LOADOUT', collection: 'COLLECTION',
    upgrades: 'UPGRADES', market: 'MARKET', quests: 'QUESTS & AWARDS', events: 'LIVE EVENTS', stats: 'STATISTICS'
  };

  const RARITY_TIERS = [
    { name: 'Common', key: 'common', max: 10, color: '#a7b0c4' },
    { name: 'Uncommon', key: 'uncommon', max: 50, color: '#60c98c' },
    { name: 'Rare', key: 'rare', max: 250, color: '#5eb7e9' },
    { name: 'Epic', key: 'epic', max: 1000, color: '#a58cff' },
    { name: 'Legendary', key: 'legendary', max: 5000, color: '#e6bf56' },
    { name: 'Mythical', key: 'mythical', max: 25000, color: '#eb8bce' },
    { name: 'Exotic', key: 'exotic', max: 100000, color: '#e48b6f' },
    { name: 'Divine', key: 'divine', max: 500000, color: '#5ee0d3' },
    { name: 'Secret', key: 'secret', max: 5000000, color: '#ed6681' },
    { name: 'Transcendent', key: 'transcendent', max: Infinity, color: '#bdc9ff' }
  ];

  const EVENTS = [
    { id: 'double-income', name: 'Double Income Day', icon: '↗', description: 'Equipped skins generate 2× passive income for this event window.', effect: '2× passive income', income: 2 },
    { id: 'pattern-rush', name: 'Mystery Pattern Rush', icon: '✧', description: 'Pattern rolls receive a stronger luck bonus. Special patterns remain independently rolled.', effect: '+4 pattern luck', patternLuck: 4 },
    { id: 'knife-rush', name: 'Knife Hunting', icon: '⌁', description: 'Knife weapon weights receive a temporary boost during the weapon selection stage.', effect: 'Knife weight boost', knifeBoost: 3 },
    { id: 'golden-skins', name: 'Golden Skin Event', icon: '✦', description: 'All newly discovered items receive a temporary market value bonus.', effect: '+25% drop value', value: 1.25 },
    { id: 'finish-frenzy', name: 'Finish Frenzy', icon: '◈', description: 'Skin finish selection gets a temporary luck bonus.', effect: '+3 finish luck', finishLuck: 3 },
    { id: 'collector-market', name: 'Collector Market', icon: '⌖', description: 'Simulated market prices trend higher during this local event.', effect: '+12% market index', market: 1.12 },
    { id: 'double-luck', name: 'Double Luck Weekend', icon: '⚡', description: 'Weapon, finish, and pattern selection all receive extra luck.', effect: '+2 luck to all layers', weaponLuck: 2, finishLuck: 2, patternLuck: 2 }
  ];

  const UPGRADE_DEFS = [
    { id: 'weaponLuck', title: 'Weapon Finder', group: 'Luck', icon: '⌖', description: 'Improves the relative weight of higher-rarity weapons. The displayed weapon odds update with every level.', max: 20, base: 180, growth: 1.48, effect: level => `Weapon luck level ${level} · stronger rare-weapon weighting` },
    { id: 'finishLuck', title: 'Finish Scanner', group: 'Luck', icon: '◈', description: 'Improves the odds of discovering higher-rarity finishes after a weapon is selected.', max: 20, base: 160, growth: 1.46, effect: level => `Finish luck level ${level} · stronger rare-finish weighting` },
    { id: 'patternLuck', title: 'Pattern Analyzer', group: 'Luck', icon: '✧', description: 'Improves special pattern selection on compatible finishes. Does not add patterns to unsupported skins.', max: 20, base: 260, growth: 1.52, effect: level => `Pattern luck level ${level} · stronger special-pattern weighting` },
    { id: 'incomeBoost', title: 'Passive Yield', group: 'Income', icon: '↗', description: 'Increases money generated by every equipped item.', max: 25, base: 120, growth: 1.42, effect: level => `+${level * 18}% passive income` },
    { id: 'offlineBoost', title: 'Offline Storage', group: 'Income', icon: '◷', description: 'Increases the share of passive income collected while you are away. Offline earnings are capped at 24 hours.', max: 10, base: 220, growth: 1.62, effect: level => `${Math.min(100, 35 + level * 6)}% offline collection` },
    { id: 'valueBoost', title: 'Market Insight', group: 'Income', icon: '⌁', description: 'Increases the starting value assigned to new drops. Market movement is applied separately.', max: 20, base: 300, growth: 1.5, effect: level => `+${level * 4}% item base value` },
    { id: 'multiRoll', title: 'Multi-Roll Protocol', group: 'Rolling', icon: '▤', description: 'Unlocks x2, x5, and x10 roll batches in order.', max: 3, base: 450, growth: 4, effect: level => ['Single roll only', 'Unlocks x2 rolls', 'Unlocks x2 and x5 rolls', 'Unlocks x2, x5, and x10 rolls'][level] },
    { id: 'autoRoll', title: 'Auto-Roll System', group: 'Rolling', icon: '⟳', description: 'Unlocks continuous auto-roll with configurable stop conditions.', max: 1, base: 1800, growth: 1, effect: level => level ? 'Auto-roll available' : 'Locked' },
    { id: 'rollSpeed', title: 'Reveal Accelerator', group: 'Rolling', icon: '»', description: 'Reduces the reveal delay. You can also disable animations in settings.', max: 5, base: 350, growth: 1.8, effect: level => `${Math.max(90, 420 - level * 55)} ms reveal time` },
    { id: 'storage', title: 'Expanded Storage', group: 'Inventory', icon: '▦', description: 'Adds more inventory slots so long collecting sessions can continue.', max: 20, base: 250, growth: 1.5, effect: level => `${100 + level * 50} item capacity` }
  ];

  const ACHIEVEMENTS = [
    { id: 'first-roll', title: 'First Contact', desc: 'Perform your first roll.', reward: 75, test: s => s.stats.totalRolls >= 1 },
    { id: 'roll-100', title: 'Getting Warm', desc: 'Reach 100 total rolls.', reward: 250, test: s => s.stats.totalRolls >= 100 },
    { id: 'roll-1000', title: 'Dedicated Collector', desc: 'Reach 1,000 total rolls.', reward: 1800, test: s => s.stats.totalRolls >= 1000 },
    { id: 'first-knife', title: 'Sharp Acquisition', desc: 'Discover any knife.', reward: 300, test: s => s.inventory.some(i => i.category === 'Knife') },
    { id: 'first-gloves', title: 'Hands On', desc: 'Discover any pair of gloves.', reward: 250, test: s => s.inventory.some(i => i.category === 'Gloves') },
    { id: 'pattern-one', title: 'Pattern Recognition', desc: 'Discover a special pattern.', reward: 450, test: s => Object.keys(s.discoveries.patterns).some(k => !k.endsWith(':Standard')) },
    { id: 'pattern-ten', title: 'Pattern Archivist', desc: 'Discover 10 different pattern variations.', reward: 1800, test: s => Object.keys(s.discoveries.patterns).length >= 10 },
    { id: 'skins-25', title: 'Growing Collection', desc: 'Discover 25 different weapon finishes.', reward: 1000, test: s => Object.keys(s.discoveries.skins).length >= 25 },
    { id: 'mythical', title: 'Mythical Find', desc: 'Find a Mythical or rarer combined drop.', reward: 2500, test: s => s.stats.bestCombinedOdds >= 25000 },
    { id: 'secret', title: 'Beyond the Odds', desc: 'Find a Secret or Transcendent combined drop.', reward: 12000, test: s => s.stats.bestCombinedOdds >= 500000 },
    { id: 'millionaire', title: 'Seven Figures', desc: 'Hold $1,000,000 at once.', reward: 10000, test: s => s.money >= 1000000 },
    { id: 'ten-million', title: 'Market Authority', desc: 'Hold $10,000,000 at once.', reward: 50000, test: s => s.money >= 10000000 },
    { id: 'blue-gem', title: 'Ocean Deep', desc: 'Discover a Blue Gem pattern.', reward: 6000, test: s => Object.keys(s.discoveries.patterns).some(k => k.endsWith(':Blue Gem')) },
    { id: 'high-tier-blue', title: 'Perfect Blue', desc: 'Discover a High-Tier Blue Gem.', reward: 18000, test: s => Object.keys(s.discoveries.patterns).some(k => k.endsWith(':High-Tier Blue Gem')) },
    { id: 'ruby', title: 'Redline Royalty', desc: 'Discover a Ruby Doppler pattern.', reward: 6500, test: s => Object.keys(s.discoveries.patterns).some(k => k.endsWith(':Ruby')) },
    { id: 'sapphire', title: 'Cold Perfection', desc: 'Discover a Sapphire Doppler pattern.', reward: 9000, test: s => Object.keys(s.discoveries.patterns).some(k => k.endsWith(':Sapphire')) },
    { id: 'black-pearl', title: 'Midnight Relic', desc: 'Discover a Black Pearl pattern.', reward: 14000, test: s => Object.keys(s.discoveries.patterns).some(k => k.endsWith(':Black Pearl')) },
    { id: 'five-slots', title: 'Fully Kitted', desc: 'Equip an item in all five loadout slots.', reward: 1200, test: s => Object.values(s.equipped).filter(Boolean).length >= 5 },
    { id: 'earn-100k', title: 'Six-Figure Turnover', desc: 'Earn $100,000 over your career.', reward: 3500, test: s => s.stats.lifetimeEarnings >= 100000 },
    { id: 'full-finish-book', title: 'Finish Encyclopedia', desc: 'Discover every available finish.', reward: 100000, test: s => Object.keys(s.discoveries.skins).length >= DATA.weapons.reduce((n,w)=>n+w.skins.length,0) }
  ];

  const random = () => {
    if (window.crypto?.getRandomValues) {
      const values = new Uint32Array(1);
      window.crypto.getRandomValues(values);
      return values[0] / 4294967296;
    }
    return Math.random();
  };
  const randomInt = (min, max) => Math.floor(random() * (max - min + 1)) + min;
  const makeId = () => window.crypto?.randomUUID ? crypto.randomUUID() : `item-${Date.now().toString(36)}-${randomInt(100000, 999999)}`;
  const clamp = (n, min, max) => Math.min(max, Math.max(min, n));
  const money = value => '$' + Number(value || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const shortMoney = value => {
    const n = Number(value || 0);
    if (n >= 1e9) return '$' + (n / 1e9).toFixed(2) + 'B';
    if (n >= 1e6) return '$' + (n / 1e6).toFixed(2) + 'M';
    if (n >= 1e4) return '$' + (n / 1e3).toFixed(1) + 'K';
    return money(n);
  };
  const fmtInt = n => Number(n || 0).toLocaleString('en-US');
  const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[ch]));
  const oddsText = inverse => {
    if (!Number.isFinite(inverse)) return '1 in ∞';
    if (inverse < 1.000001) return '1 in 1';
    if (inverse < 1000000000000) return '1 in ' + Number(inverse.toPrecision(9)).toLocaleString('en-US', { maximumFractionDigits: 7 });
    return '1 in ' + inverse.toExponential(7).replace('+', '');
  };
  const tierFor = inverse => RARITY_TIERS.find(t => inverse < t.max) || RARITY_TIERS[RARITY_TIERS.length - 1];
  const wearFor = f => f <= .07 ? 'Factory New' : f <= .15 ? 'Minimal Wear' : f <= .38 ? 'Field-Tested' : f <= .45 ? 'Well-Worn' : 'Battle-Scarred';
  const wearMultiplier = wear => ({ 'Factory New':1.25, 'Minimal Wear':1.12, 'Field-Tested':.96, 'Well-Worn':.82, 'Battle-Scarred':.68 }[wear] || 1);
  const itemKey = (weaponId, skinName) => `${weaponId}:${skinName}`;
  const patternKey = (weaponId, skinName, patternName) => `${weaponId}:${skinName}:${patternName}`;

  function defaultState() {
    return {
      version: 1, savedAt: 0, money: 250, inventory: [], equipped: { primary:null, secondary:null, smg:null, knife:null, gloves:null },
      upgrades: Object.fromEntries(UPGRADE_DEFS.map(u => [u.id, 0])),
      stats: { totalRolls:0, weaponsDiscovered:0, skinsDiscovered:0, patternsDiscovered:0, totalSold:0, totalSales:0, moneySpent:0, lifetimeEarnings:0, passiveEarned:0, questEarned:0, playSeconds:0, bestCombinedOdds:0, highestValue:0, bestDrop:null, highestValueDrop:null, lastDrop:null },
      discoveries: { weapons:{}, skins:{}, patterns:{} }, achievements:[],
      quests: { date:'', items:[] },
      settings: { animations:true, sound:false, volume:0.25, compact:false },
      rollHistory:[], marketIndex:1, marketHistory:[], lastMarketUpdate:Date.now(), lastTick:Date.now()
    };
  }

  let state = defaultState();
  let currentPage = 'dashboard';
  let currentRollMode = 1;
  let lastDrop = null;
  let isRolling = false;
  let autoActive = false;
  let autoBusy = false;
  let audioContext = null;
  const ui = { search:'', rarity:'all', sort:'newest', filter:'all', selected:new Set(), collectionTab:'skins', collectionFilter:'all', autoStopType:'none', autoStopValue:'Legendary', inspectId:null };

  function openDatabase() {
    return new Promise(resolve => {
      if (!('indexedDB' in window)) return resolve(null);
      const request = indexedDB.open(DB_NAME, 1);
      request.onupgradeneeded = () => {
        const db = request.result;
        if (!db.objectStoreNames.contains(DB_STORE)) db.createObjectStore(DB_STORE);
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => resolve(null);
    });
  }
  let dbPromise;
  const getDb = () => dbPromise || (dbPromise = openDatabase());
  async function idbRead() {
    const db = await getDb(); if (!db) return null;
    return new Promise(resolve => {
      try {
        const req = db.transaction(DB_STORE, 'readonly').objectStore(DB_STORE).get('save');
        req.onsuccess = () => resolve(req.result || null); req.onerror = () => resolve(null);
      } catch { resolve(null); }
    });
  }
  async function idbWrite(data) {
    const db = await getDb(); if (!db) return;
    return new Promise(resolve => {
      try {
        const tx = db.transaction(DB_STORE, 'readwrite');
        tx.objectStore(DB_STORE).put(data, 'save');
        tx.oncomplete = () => resolve(true); tx.onerror = () => resolve(false);
      } catch { resolve(false); }
    });
  }
  function normalizeState(raw) {
    const base = defaultState();
    if (!raw || typeof raw !== 'object') return base;
    const merged = { ...base, ...raw };
    merged.stats = { ...base.stats, ...(raw.stats || {}) };
    merged.upgrades = { ...base.upgrades, ...(raw.upgrades || {}) };
    merged.settings = { ...base.settings, ...(raw.settings || {}) };
    merged.equipped = { ...base.equipped, ...(raw.equipped || {}) };
    merged.discoveries = { weapons:{}, skins:{}, patterns:{}, ...(raw.discoveries || {}) };
    merged.inventory = Array.isArray(raw.inventory) ? raw.inventory.filter(x => x && x.id && x.weaponId) : [];
    merged.rollHistory = Array.isArray(raw.rollHistory) ? raw.rollHistory.slice(0, 60) : [];
    merged.achievements = Array.isArray(raw.achievements) ? raw.achievements : [];
    merged.quests = raw.quests && Array.isArray(raw.quests.items) ? raw.quests : base.quests;
    merged.marketHistory = Array.isArray(raw.marketHistory) ? raw.marketHistory.slice(-40) : [];
    return merged;
  }
  async function loadState() {
    let local = null;
    try { local = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null'); } catch { local = null; }
    const indexed = await idbRead();
    const raw = (indexed?.savedAt || 0) > (local?.savedAt || 0) ? indexed : local;
    state = normalizeState(raw);
    const now = Date.now();
    const elapsed = clamp((now - (state.lastTick || now)) / 1000, 0, 86400);
    if (elapsed > 20) {
      const efficiency = clamp(.35 + (state.upgrades.offlineBoost || 0) * .06, .35, .95);
      const earned = incomePerSecond() * elapsed * efficiency;
      if (earned > 0) {
        state.money += earned;
        state.stats.lifetimeEarnings += earned;
        state.stats.passiveEarned += earned;
        window.__offlineReport = { earned, seconds: elapsed, efficiency };
      }
    }
    state.lastTick = now;
    if (!state.marketHistory.length) state.marketHistory = Array.from({length:18}, (_, i) => ({ time: now - (17-i)*60000, value: 1 + Math.sin(i/3)*.035 }));
    refreshDailyQuests();
    updateAchievements();
    saveState();
  }
  function saveState() {
    state.savedAt = Date.now();
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch (err) { toast('Save storage is full', 'Sell items or export your save to free space.'); }
    idbWrite(state);
  }

  function currentEvent() {
    const day = new Date().getDay();
    if (day === 0 || day === 6) return EVENTS[6];
    // Weekday event rotation advances each week so all six weekday events recur.
    const weekIndex = Math.floor(Date.now() / 604800000);
    return EVENTS[(weekIndex + day - 1) % 6] || EVENTS[0];
  }
  function eventModifiers() {
    const event = currentEvent();
    return {
      weaponLuck: event.weaponLuck || 0, finishLuck: event.finishLuck || 0, patternLuck: event.patternLuck || 0,
      knifeBoost: event.knifeBoost || 1, income: event.income || 1, value: event.value || 1, market: event.market || 1
    };
  }
  function luckLevels() {
    const ev = eventModifiers();
    return {
      weapon: (state.upgrades.weaponLuck || 0) + ev.weaponLuck,
      skin: (state.upgrades.finishLuck || 0) + ev.finishLuck,
      pattern: (state.upgrades.patternLuck || 0) + ev.patternLuck
    };
  }
  function exponentFor(level) { return Math.max(.2, 1 - Math.max(0, level) * .055); }
  function weightsFor(list, level, kind = '', ignoreEvent = false) {
    const exponent = exponentFor(level);
    const ev = ignoreEvent ? { knifeBoost:1 } : eventModifiers();
    return list.map(entry => {
      let weight = Math.pow(1 / Math.max(.000001, Number(entry.odds) || 1), exponent);
      if (kind === 'weapon' && entry.category === 'Knife') weight *= ev.knifeBoost;
      return weight;
    });
  }
  function probabilityMap(list, level, kind = '', ignoreEvent = false) {
    const weights = weightsFor(list, level, kind, ignoreEvent);
    const total = weights.reduce((sum, w) => sum + w, 0) || 1;
    return list.map((entry, i) => ({ entry, probability: weights[i] / total }));
  }
  function weightedPick(list, level, kind = '') {
    const options = probabilityMap(list, level, kind);
    const r = random(); let cursor = 0;
    for (const option of options) { cursor += option.probability; if (r <= cursor) return option; }
    return options[options.length - 1];
  }

  function makeDrop() {
    const luck = luckLevels();
    const weaponPick = weightedPick(DATA.weapons, luck.weapon, 'weapon');
    const weapon = weaponPick.entry;
    const skinPick = weightedPick(weapon.skins, luck.skin, 'skin');
    const finish = skinPick.entry;
    let pattern = { name:'N/A', odds:1, multiplier:1, probability:1, seed:null };
    if (finish.patterns?.length) {
      const patternPick = weightedPick(finish.patterns, luck.pattern, 'pattern');
      pattern = { ...patternPick.entry, probability:patternPick.probability, seed:randomInt(1,1000) };
    }
    const baseWeaponProbability = probabilityMap(DATA.weapons, 0, 'weapon', true).find(x=>x.entry.id===weapon.id)?.probability || weaponPick.probability;
    const baseSkinProbability = probabilityMap(weapon.skins, 0, 'skin', true).find(x=>x.entry.name===finish.name)?.probability || skinPick.probability;
    const basePatternProbability = finish.patterns?.length ? (probabilityMap(finish.patterns, 0, 'pattern', true).find(x=>x.entry.name===pattern.name)?.probability || pattern.probability) : 1;
    const float = random();
    const wear = wearFor(float);
    const eventValue = eventModifiers().value;
    const valueMultiplier = (1 + Math.log10(weapon.odds + 1) * .19) * wearMultiplier(wear) * pattern.multiplier * (1 + (state.upgrades.valueBoost || 0) * .04) * eventValue;
    const baseValue = Math.max(.25, finish.value * valueMultiplier);
    const combinedOdds = (1 / weaponPick.probability) * (1 / skinPick.probability) * (1 / pattern.probability);
    const tier = tierFor(combinedOdds);
    const isNewWeapon = !state.discoveries.weapons[weapon.id];
    const key = itemKey(weapon.id, finish.name);
    const isNewSkin = !state.discoveries.skins[key];
    const pKey = pattern.name !== 'N/A' ? patternKey(weapon.id, finish.name, pattern.name) : null;
    const isNewPattern = pKey ? !state.discoveries.patterns[pKey] : false;
    return {
      id:makeId(), weaponId:weapon.id, weapon:weapon.name, category:weapon.category, model:weapon.model,
      skin:finish.name, color:finish.color, float, wear, pattern:pattern.name, patternSeed:pattern.seed,
      patternMultiplier:pattern.multiplier, weaponOdds:1 / weaponPick.probability, skinOdds:1 / skinPick.probability,
      patternOdds:1 / pattern.probability, combinedOdds,
      baseWeaponOdds:1 / baseWeaponProbability, baseSkinOdds:1 / baseSkinProbability,
      basePatternOdds:1 / basePatternProbability, baseCombinedOdds:(1/baseWeaponProbability)*(1/baseSkinProbability)*(1/basePatternProbability),
      tier:tier.name, tierKey:tier.key, tierColor:tier.color,
      baseValue, createdAt:Date.now(), favorite:false, locked:false, isNewWeapon, isNewSkin, isNewPattern
    };
  }
  function currentPrice(item) { return Math.max(.01, item.baseValue * state.marketIndex * eventModifiers().market); }
  function incomePerSecond() {
    const base = Object.values(state.equipped).filter(Boolean).map(id => state.inventory.find(i => i.id === id)).filter(Boolean).reduce((sum, item) => {
      const rarityFactor = 1 + Math.min(1.8, Math.log10(Math.max(1, item.combinedOdds)) * .12);
      return sum + Math.max(.015, Math.sqrt(currentPrice(item)) * .012) * rarityFactor;
    }, 0);
    return base * (1 + (state.upgrades.incomeBoost || 0) * .18) * eventModifiers().income;
  }
  function capacity() { return 100 + (state.upgrades.storage || 0) * 50; }
  function equipmentSlot(category) {
    return ({ Rifle:'primary', Pistol:'secondary', SMG:'smg', Knife:'knife', Gloves:'gloves' })[category] || null;
  }
  function getEquipped(id) { return Object.values(state.equipped).includes(id); }

  function updateDiscoveries(item) {
    state.discoveries.weapons[item.weaponId] = true;
    state.discoveries.skins[itemKey(item.weaponId, item.skin)] = true;
    if (item.pattern !== 'N/A') state.discoveries.patterns[patternKey(item.weaponId, item.skin, item.pattern)] = true;
    state.stats.weaponsDiscovered = Object.keys(state.discoveries.weapons).length;
    state.stats.skinsDiscovered = Object.keys(state.discoveries.skins).length;
    state.stats.patternsDiscovered = Object.keys(state.discoveries.patterns).length;
    state.stats.highestValue = Math.max(state.stats.highestValue || 0, item.baseValue);
    state.stats.bestCombinedOdds = Math.max(state.stats.bestCombinedOdds || 0, item.combinedOdds);
    if (!state.stats.bestDrop || item.combinedOdds > state.stats.bestDrop.combinedOdds) state.stats.bestDrop = { ...item };
    if (!state.stats.highestValueDrop || item.baseValue > state.stats.highestValueDrop.baseValue) state.stats.highestValueDrop = { ...item };
  }
  function addQuestProgress(type, amount = 1, item = null) {
    for (const quest of state.quests.items) {
      if (quest.claimed || quest.type !== type) continue;
      if (type === 'rare' && item && item.combinedOdds < (quest.threshold || 1000)) continue;
      if (type === 'pattern' && item && item.pattern === 'N/A') continue;
      quest.progress = Math.min(quest.target, quest.progress + amount);
      if (quest.progress >= quest.target && !quest.claimed) {
        quest.claimed = true;
        state.money += quest.reward;
        state.stats.lifetimeEarnings += quest.reward;
        state.stats.questEarned += quest.reward;
        setTimeout(() => toast('Quest complete', `${quest.title} · ${money(quest.reward)} claimed.`), 80);
      }
    }
  }
  function refreshDailyQuests() {
    const date = new Date().toLocaleDateString('en-CA');
    if (state.quests.date === date && state.quests.items?.length) return;
    const templates = [
      { id:'daily-rolls', title:'Warm Up', description:'Perform 30 rolls.', type:'roll', target:30, reward:240 },
      { id:'daily-sell', title:'Market Cleanup', description:'Sell 3 items.', type:'sell', target:3, reward:190 },
      { id:'daily-pattern', title:'Pattern Watch', description:'Discover 1 supported pattern.', type:'pattern', target:1, reward:360 },
      { id:'daily-earn', title:'Cash Flow', description:'Earn $500 from sales and passive income.', type:'earn', target:500, reward:260 },
      { id:'daily-equip', title:'Ready Up', description:'Equip 1 item to your loadout.', type:'equip', target:1, reward:150 },
      { id:'daily-rare', title:'Rare Signal', description:'Find an item rarer than 1 in 1,000.', type:'rare', target:1, threshold:1000, reward:450 }
    ];
    const offset = Math.floor(Date.now() / 86400000) % templates.length;
    state.quests = { date, items:[templates[offset], templates[(offset + 2) % templates.length], templates[(offset + 4) % templates.length]].map(q => ({ ...q, progress:0, claimed:false })) };
  }
  function updateAchievements() {
    for (const achievement of ACHIEVEMENTS) {
      if (!state.achievements.includes(achievement.id) && achievement.test(state)) {
        state.achievements.push(achievement.id);
        state.money += achievement.reward;
        state.stats.lifetimeEarnings += achievement.reward;
        toast('Achievement unlocked', `${achievement.title} · ${money(achievement.reward)} reward.`);
      }
    }
  }
  function addDropToInventory(item) {
    updateDiscoveries(item);
    state.inventory.unshift(item);
    state.stats.totalRolls += 1;
    state.stats.lastDrop = item.id;
    state.rollHistory.unshift({ id:item.id, weapon:item.weapon, skin:item.skin, pattern:item.pattern, tier:item.tier, odds:item.combinedOdds, value:item.baseValue, time:item.createdAt, color:item.color, model:item.model, category:item.category });
    state.rollHistory = state.rollHistory.slice(0, 60);
    addQuestProgress('roll', 1, item);
    if (item.isNewPattern) addQuestProgress('pattern', 1, item);
    if (item.combinedOdds >= 1000) addQuestProgress('rare', 1, item);
    addQuestProgress('earn', 0, item);
    updateAchievements();
  }
  function stopConditionMet(item) {
    const type = ui.autoStopType;
    if (!type || type === 'none') return false;
    if (type === 'rarity') {
      const target = RARITY_TIERS.findIndex(t => t.name === ui.autoStopValue);
      return RARITY_TIERS.findIndex(t => t.name === item.tier) >= target;
    }
    if (type === 'value') return currentPrice(item) >= Math.max(0, Number(ui.autoStopValue) || 0);
    if (type === 'newWeapon') return item.isNewWeapon;
    if (type === 'newSkin') return item.isNewSkin;
    if (type === 'pattern') return item.isNewPattern;
    if (type === 'weapon') return item.weaponId === ui.autoStopValue;
    return false;
  }

  function sound(frequency = 540, duration = .075) {
    if (!state.settings.sound) return;
    try {
      audioContext ||= new (window.AudioContext || window.webkitAudioContext)();
      const osc = audioContext.createOscillator(); const gain = audioContext.createGain();
      osc.type = 'sine'; osc.frequency.setValueAtTime(frequency, audioContext.currentTime);
      gain.gain.setValueAtTime(state.settings.volume * .08, audioContext.currentTime);
      gain.gain.exponentialRampToValueAtTime(.001, audioContext.currentTime + duration);
      osc.connect(gain); gain.connect(audioContext.destination); osc.start(); osc.stop(audioContext.currentTime + duration);
    } catch { /* Audio is optional and may be blocked by the browser. */ }
  }
  function toast(title, description = '') {
    const stack = $('#toastStack'); if (!stack) return;
    const node = document.createElement('div'); node.className = 'toast';
    node.innerHTML = `<span class="toast-mark"></span><div><strong>${esc(title)}</strong><span>${esc(description)}</span></div>`;
    stack.append(node); setTimeout(() => node.remove(), 3600);
  }

  async function rollBatch(requestedCount, auto = false) {
    if (isRolling) return null;
    const maxUnlocked = [1,2,5,10][state.upgrades.multiRoll || 0] || 1;
    const count = Math.min(requestedCount, maxUnlocked, capacity() - state.inventory.length);
    if (count <= 0) { if (state.inventory.length >= capacity()) toast('Inventory full', 'Sell items or buy more storage.'); return null; }
    const totalCost = count * ROLL_COST;
    if (state.money < totalCost) { toast('Not enough balance', `You need ${money(totalCost)} for ${count} roll${count > 1 ? 's' : ''}.`); return null; }
    isRolling = true;
    state.money -= totalCost; state.stats.moneySpent += totalCost;
    const drops = [];
    for (let i = 0; i < count; i++) {
      const item = makeDrop(); addDropToInventory(item); drops.push(item);
    }
    lastDrop = drops[drops.length - 1];
    const stopNow = auto && drops.some(stopConditionMet);
    state.stats.playSeconds = state.stats.playSeconds || 0;
    sound(lastDrop.tierKey === 'common' ? 430 : 790, .11);
    const stage = $('.roll-stage');
    if (stage && state.settings.animations) {
      stage.classList.add('rolling');
      stage.innerHTML = `<div class="stage-grid"></div><div class="stage-placeholder"><div class="placeholder-orbit"><span>◈</span></div><strong>ANALYZING DROP</strong><small>GENERATING WEAPON · FINISH · PATTERN</small></div>`;
    }
    updateHeader();
    const delay = state.settings.animations ? Math.max(90, 420 - (state.upgrades.rollSpeed || 0) * 55) : 0;
    if (delay) await new Promise(resolve => setTimeout(resolve, delay));
    isRolling = false;
    render();
    if (stopNow) {
      autoActive = false;
      toast('Auto-roll stopped', 'Your selected stop condition was reached.');
    }
    if (lastDrop.combinedOdds >= 25000 || ['Blue Gem','High-Tier Blue Gem','Ruby','Sapphire','Black Pearl','Perfect Full Fade','Fire & Ice'].includes(lastDrop.pattern)) showRareAnnouncement(lastDrop);
    saveState();
    return lastDrop;
  }
  async function autoRollStep() {
    if (!autoActive || autoBusy) return;
    autoBusy = true;
    const result = await rollBatch(1, true);
    autoBusy = false;
    if (!autoActive) return;
    if (!result) { autoActive = false; render(); return; }
    setTimeout(autoRollStep, 220);
  }
  function toggleAutoRoll() {
    if (!(state.upgrades.autoRoll > 0)) { toast('Auto-roll locked', 'Purchase the Auto-Roll System in Upgrades first.'); return; }
    autoActive = !autoActive;
    if (autoActive) { toast('Auto-roll started', 'It will stop when your selected condition is met.'); autoRollStep(); }
    else toast('Auto-roll paused', 'You can resume whenever you are ready.');
    render();
  }

  function sellItem(id) {
    const item = state.inventory.find(i => i.id === id);
    if (!item) return;
    if (item.locked || getEquipped(id)) { toast('Item protected', 'Unequip and unlock this item before selling it.'); return; }
    const value = currentPrice(item);
    state.inventory = state.inventory.filter(i => i.id !== id);
    state.money += value; state.stats.totalSold++; state.stats.totalSales += value; state.stats.lifetimeEarnings += value;
    addQuestProgress('sell', 1); addQuestProgress('earn', value);
    ui.selected.delete(id); updateAchievements(); saveState(); render(); toast('Item sold', `${item.weapon} | ${item.skin} · ${money(value)}`); sound(680,.06);
  }
  function bulkSell() {
    const ids = [...ui.selected];
    const sellable = state.inventory.filter(i => ids.includes(i.id) && !i.locked && !getEquipped(i.id));
    if (!sellable.length) { toast('Nothing to sell', 'Select unlocked items that are not equipped.'); return; }
    const total = sellable.reduce((sum, item) => sum + currentPrice(item), 0);
    const sellIds = new Set(sellable.map(i => i.id));
    state.inventory = state.inventory.filter(i => !sellIds.has(i.id));
    state.money += total; state.stats.totalSold += sellable.length; state.stats.totalSales += total; state.stats.lifetimeEarnings += total;
    addQuestProgress('sell', sellable.length); addQuestProgress('earn', total);
    ui.selected.clear(); updateAchievements(); saveState(); render(); toast('Bulk sale complete', `${sellable.length} items sold for ${money(total)}.`);
  }
  function equipItem(id, slotOverride = null) {
    const item = state.inventory.find(i => i.id === id); if (!item) return;
    const slot = slotOverride || equipmentSlot(item.category);
    if (!slot) { toast('Cannot equip', 'This item category has no equipment slot.'); return; }
    if (getEquipped(id)) {
      state.equipped[slot] = null;
    } else {
      state.equipped[slot] = id;
    }
    addQuestProgress('equip', 1); saveState(); render(); toast(getEquipped(id) ? 'Item equipped' : 'Item unequipped', `${item.weapon} · ${slot.toUpperCase()}`);
  }
  function toggleFavorite(id) {
    const item = state.inventory.find(i => i.id === id); if (!item) return;
    item.favorite = !item.favorite; saveState(); render();
  }
  function toggleLock(id) {
    const item = state.inventory.find(i => i.id === id); if (!item) return;
    item.locked = !item.locked; saveState(); render();
    toast(item.locked ? 'Item locked' : 'Item unlocked', item.locked ? 'This item is protected from selling.' : 'This item can now be sold.');
  }

  function upgradeCost(def) { return Math.round(def.base * Math.pow(def.growth, state.upgrades[def.id] || 0)); }
  function buyUpgrade(id) {
    const def = UPGRADE_DEFS.find(x => x.id === id); if (!def) return;
    const level = state.upgrades[id] || 0;
    if (level >= def.max) return;
    const cost = upgradeCost(def);
    if (state.money < cost) { toast('Not enough balance', `You need ${money(cost)} for ${def.title}.`); return; }
    state.money -= cost; state.stats.moneySpent += cost; state.upgrades[id] = level + 1;
    saveState(); render(); toast('Upgrade purchased', `${def.title} · Level ${level + 1}`); sound(730,.09);
  }

  function itemArt(item, extraClass = '') {
    const model = item.model || 'rifle';
    const color = item.color || '#8290a6';
    const accentMap = { 'Blue Gem':'#3d9bd6','High-Tier Blue Gem':'#37b9ef','Mixed Blue & Gold':'#cba94f','Gold Gem':'#d7b54b','Ruby':'#d93f63','Sapphire':'#3b83e8','Black Pearl':'#8264ac','Full Fade':'#db8c66','High Fade':'#c37ace','Perfect Web':'#ed5364','Fire & Ice':'#75cde9' };
    const accent = accentMap[item.pattern] || (item.pattern?.includes('Fade') ? '#c780ce' : '#d4bc7a');
    const id = 'g' + String(item.id || item.weaponId || 'drop').replace(/[^a-z0-9]/gi,'').slice(-16);
    const seedShift = (Number(item.patternSeed || 0) % 19) - 9;
    const texture = item.pattern && item.pattern !== 'N/A'
      ? `<g transform="translate(${seedShift} 0)"><path d="M155 50l28 -18 27 19 -22 22 -30 -7zM218 50l20 -14 30 16 -22 23 -28 -7zM271 51l20 -14 20 17 -20 19 -24 -5z" fill="${accent}" opacity=".48"/><path d="M155 86l26 -14 21 12 -26 15zM230 83l25 -14 20 12 -25 16z" fill="${accent}" opacity=".35"/><path d="M${165 + Math.abs(seedShift)} 38v47M${242 - seedShift} 43v42M${292 + seedShift} 47v35" stroke="${accent}" stroke-width="3" opacity=".28"/></g>` : '';
    const wearOpacity = item.float == null ? 0 : clamp((item.float - .08) * 1.15, 0, .82);
    const wearMarks = wearOpacity > .08 ? `<path d="M153 54l19 7m8 14 14 -5m21 11 15 -8m30 -17 16 4m22 19 17 -6" stroke="#e5e8f1" stroke-width="2" stroke-linecap="round" opacity="${wearOpacity.toFixed(2)}"/><path d="M184 61l8 4m54 26 8 -4m43 -29 9 3" stroke="#111827" stroke-width="3" stroke-linecap="round" opacity="${(wearOpacity*.7).toFixed(2)}"/>` : '';
    let body = '';
    if (model === 'knife') {
      body = `<path d="M94 75 Q160 42 245 38 Q298 34 385 58 Q324 75 263 87 L190 91 143 107 102 99Z" fill="url(#${id})" stroke="#e0e5f0" stroke-opacity=".26" stroke-width="2"/><path d="M99 76l72 2 14 20 -35 23 -47 -8 -24 -12z" fill="#262d3d" stroke="#b6c0d4" stroke-opacity=".4" stroke-width="2"/><path d="M111 84l42 4M116 93l40 5M126 103l34 4" stroke="${accent}" stroke-width="4" stroke-linecap="round" opacity=".8"/><path d="M173 78 Q272 42 363 57" stroke="#f4f5ff" stroke-width="2" opacity=".28" fill="none"/>`;
    } else if (model === 'gloves') {
      body = `<path d="M95 92Q82 82 91 64l12 -29q5 -10 13 -5 8 3 3 14l-5 16 15 -37q5 -10 14 -5 8 4 2 16l-10 28 20 -34q7 -10 15 -4 7 5 0 16l-18 31 24 -25q9 -8 15 -1 5 7 -3 15l-27 32q-17 21 -43 8z" fill="url(#${id})" stroke="#d9dfea" stroke-opacity=".35" stroke-width="2"/><path d="M234 92q-13 -10 -4 -28l16 -30q6 -10 14 -5 7 4 1 15l-8 15 17 -35q5 -10 14 -5 8 4 2 16l-11 25 21 -31q7 -9 15 -3 6 5 0 15l-19 28 24 -23q8 -8 15 -1 5 6 -3 15l-27 31q-18 19 -42 8z" fill="url(#${id})" stroke="#d9dfea" stroke-opacity=".35" stroke-width="2"/><path d="M97 80l73 11M237 80l73 11" stroke="${accent}" stroke-width="7" opacity=".85"/>`;
    } else if (model === 'pistol') {
      body = `<path d="M99 50h186l38 13 -8 20H188l-4 29 -21 5 -10 -35H99z" fill="url(#${id})" stroke="#dfe5f0" stroke-opacity=".25" stroke-width="2"/><path d="M287 57h91v13h-91z" fill="#495366"/><path d="M197 83h38v42h-38z" fill="#252c3b" stroke="#8994aa" stroke-opacity=".4"/><path d="M114 44h130v6H114z" fill="#d8e0ed" opacity=".18"/><path d="M119 57l50 0M177 57l36 0" stroke="${accent}" stroke-width="5" opacity=".8"/>`;
    } else {
      const length = model === 'sniper' ? 355 : model === 'shotgun' ? 315 : model === 'heavy' ? 320 : model === 'smg' ? 282 : 335;
      body = `<path d="M46 68h46l28 -10h${length-130}l24 10h68v14h-45l-19 15h-80l-13 -15H46z" fill="url(#${id})" stroke="#dfe5f0" stroke-opacity=".25" stroke-width="2"/><path d="M${length+12} 70h45v8h-45z" fill="#647086"/><path d="M${length+44} 67h26v13h-26z" fill="#394356"/><path d="M117 59l-15 -18h-18v28h26z" fill="#222a39" stroke="#8b96a9" stroke-opacity=".4"/><path d="M190 90h34l-4 38h-27z" fill="#252d3d" stroke="#8994aa" stroke-opacity=".4"/><path d="M250 83l20 2 -5 34 -26 -1z" fill="#323b4d"/><path d="M70 64h42v13H70z" fill="#30394a"/><path d="M135 55h120" stroke="#e9edf4" stroke-opacity=".16" stroke-width="2"/><path d="M137 62l29 0M180 62l31 0M228 62l26 0" stroke="${accent}" stroke-width="5" opacity=".85"/>`;
      if (model === 'sniper') body += `<path d="M164 45h105v12H164z" fill="#313c50"/><path d="M177 44v-10h80v10" stroke="#8c98aa" stroke-width="4" fill="none"/>`;
      if (model === 'heavy') body += `<path d="M160 95h84v18h-84z" fill="#252d3d"/><path d="M172 113h60v8h-60z" fill="#717d90"/>`;
    }
    const textureOverlay = model === 'knife' ? `<path d="M185 77Q275 48 363 59" stroke="${accent}" stroke-width="9" opacity=".58" fill="none"/>` : texture;
    return `<svg class="weapon-art ${extraClass}" viewBox="0 0 440 145" role="img" aria-label="${esc(item.weapon || 'Weapon')} illustration"><defs><linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${color}"/><stop offset=".48" stop-color="${accent}" stop-opacity=".85"/><stop offset="1" stop-color="#202638"/></linearGradient></defs><g filter="drop-shadow(0 9px 7px #0009)">${body}${textureOverlay}${wearMarks}</g><path d="M34 132h374" stroke="#bfc6d9" opacity=".12" stroke-width="1"/></svg>`;
  }

  function itemCard(item, selectable = false) {
    const equipped = getEquipped(item.id);
    return `<article class="item-card" data-action="inspect" data-id="${esc(item.id)}" style="--tier-color:${item.tierColor || tierFor(item.combinedOdds).color}">
      ${selectable ? `<input class="item-check" type="checkbox" data-action="select-item" data-id="${esc(item.id)}" ${ui.selected.has(item.id) ? 'checked' : ''} aria-label="Select ${esc(item.weapon)}">` : ''}
      <button class="favorite-mark" data-action="favorite" data-id="${esc(item.id)}" title="Toggle favorite">${item.favorite ? '★' : '☆'}${item.locked ? ' · L' : ''}</button>
      <div class="item-card-art">${itemArt(item)}</div><div class="rarity-line" style="--tier-color:${item.tierColor || tierFor(item.combinedOdds).color}"></div>
      <div class="item-card-info"><div class="item-card-name">${esc(item.weapon)}</div><div class="item-card-finish">${esc(item.skin)}${item.pattern !== 'N/A' ? ` · ${esc(item.pattern)}` : ''}</div>
      <div class="item-card-meta"><span class="rarity-tag rarity-${esc(item.tierKey || tierFor(item.combinedOdds).key)}">${esc(item.tier || tierFor(item.combinedOdds).name)}</span><span class="item-card-value">${money(currentPrice(item))}</span></div>
      <div class="item-card-finish mono">${oddsText(item.combinedOdds)}${equipped ? ' · EQUIPPED' : ''}</div></div></article>`;
  }

  function headerHtml(kicker, title, desc, right = '') {
    return `<div class="page-heading"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${right ? `<div class="heading-meta">${right}</div>` : ''}</div>`;
  }
  function statCard(label, value, foot, extra = '') {
    return `<div class="panel stat-card"><div class="stat-label">${esc(label)}</div><div class="stat-value ${extra}">${value}</div><div class="stat-foot">${esc(foot)}</div></div>`;
  }
  function eventTimeLeft() {
    const now = new Date(); const end = new Date(now); end.setHours(24,0,0,0);
    const mins = Math.max(0, Math.floor((end - now) / 60000));
    return `${Math.floor(mins/60)}h ${mins%60}m remaining`;
  }
  function updateHeader() {
    const moneyEl = $('#topMoney'), rollsEl = $('#topRolls'), incomeEl = $('#topIncome');
    if (moneyEl) moneyEl.textContent = shortMoney(state.money);
    if (rollsEl) rollsEl.textContent = fmtInt(state.stats.totalRolls);
    if (incomeEl) incomeEl.textContent = money(incomePerSecond());
    const event = currentEvent();
    const side = $('#sidebarEvent');
    if (side) side.innerHTML = `<div class="event-mini-top"><span class="live-dot"></span> ACTIVE EVENT</div><strong>${esc(event.name)}</strong><span class="muted">${esc(event.effect)} · ${eventTimeLeft()}</span>`;
  }

  function renderDashboard() {
    const luck = luckLevels();
    const totalDiscovered = Object.keys(state.discoveries.skins).length;
    const pct = Math.round(totalDiscovered / DATA.weapons.reduce((n,w) => n + w.skins.length, 0) * 100);
    const recent = state.rollHistory.slice(0, 5);
    const mode = currentRollMode;
    const maxMulti = [1,2,5,10][state.upgrades.multiRoll || 0] || 1;
    const stopOptions = `<option value="none">No stop condition</option><option value="rarity">Stop at rarity</option><option value="value">Stop at item value</option><option value="newWeapon">Stop on new weapon</option><option value="newSkin">Stop on new finish</option><option value="pattern">Stop on new pattern</option><option value="weapon">Stop on selected weapon</option>`;
    const stopValue = ui.autoStopType === 'rarity'
      ? `<select id="autoStopValue" class="auto-stop-value">${RARITY_TIERS.map(t => `<option ${ui.autoStopValue===t.name?'selected':''}>${t.name}</option>`).join('')}</select>`
      : ui.autoStopType === 'weapon'
        ? `<select id="autoStopValue" class="auto-stop-value">${DATA.weapons.map(w => `<option value="${w.id}" ${ui.autoStopValue===w.id?'selected':''}>${esc(w.name)}</option>`).join('')}</select>`
        : ui.autoStopType === 'value'
          ? `<input id="autoStopValue" class="auto-stop-value" type="number" min="0" step="10" value="${esc(ui.autoStopValue)}" placeholder="Minimum $ value">` : '';
    return `${headerHtml('THE DROP FLOOR','Roll for something rare.','Every drop is generated from three independent layers: weapon, finish, and supported pattern.',`<span class="chip purple">${fmtInt(state.stats.totalRolls)} TOTAL ROLLS</span><span class="chip good">${pct}% COLLECTION</span>`)}
      <div class="stat-grid">
        ${statCard('TOTAL INVENTORY',fmtInt(state.inventory.length),`${capacity()} storage slots`)}
        ${statCard('COLLECTION VALUE',shortMoney(state.inventory.reduce((sum,i)=>sum+currentPrice(i),0)),'Live simulated item prices','gold')}
        ${statCard('BEST COMBINED DROP',state.stats.bestCombinedOdds ? oddsText(state.stats.bestCombinedOdds) : '—','Your rarest recorded combination','purple-text')}
        ${statCard('PASSIVE INCOME',money(incomePerSecond())+'/sec','From equipped skins','green')}
      </div>
      <div class="roll-layout">
        <section class="panel roll-panel"><div class="roll-panel-content">
          <div class="panel-head" style="padding:0 0 0;border:0"><div><div class="section-kicker">RNG ENGINE / LIVE</div><div class="panel-title" style="margin-top:5px">Weapon discovery terminal</div></div><span class="chip good">● SYSTEM ONLINE</span></div>
          <div class="roll-stage ${lastDrop ? 'has-result' : ''} ${lastDrop ? `reveal-${lastDrop.tierKey}` : ''}">${lastDrop ? `<div class="stage-grid"></div><div class="stage-result">${itemArt(lastDrop)}<div class="stage-name">${esc(lastDrop.weapon)}</div><div class="stage-finish">${esc(lastDrop.skin)}${lastDrop.pattern !== 'N/A' ? ` · ${esc(lastDrop.pattern)}` : ''}</div><div class="stage-value">${money(currentPrice(lastDrop))} <span class="rarity-tag rarity-${lastDrop.tierKey}">${esc(lastDrop.tier)}</span></div><div class="mono muted" style="font-size:9px;margin-top:6px">${oddsText(lastDrop.combinedOdds)} · FLOAT ${lastDrop.float.toFixed(5)}</div></div>` : `<div class="stage-grid"></div><div class="stage-placeholder"><div class="placeholder-orbit"><span>◈</span></div><strong>READY TO ROLL</strong><small>YOUR NEXT DROP IS ONE ROLL AWAY</small></div>`}</div>
          <div class="roll-controls"><div class="roll-modes">${[1,2,5,10].map(n => `<button class="roll-mode ${mode===n?'active':''}" data-action="roll-mode" data-count="${n}" ${n>maxMulti?'disabled':''}>x${n}</button>`).join('')}</div><button class="roll-btn" data-action="roll" ${isRolling?'disabled':''}>${isRolling?'ROLLING…':`ROLL ${mode>1?`x${mode}`:''}`}</button></div>
          <div class="roll-cost">${money(ROLL_COST * mode)} PER BATCH · ${money(ROLL_COST)} EACH ROLL · INVENTORY ${state.inventory.length}/${capacity()}</div>
          <div class="roll-bottom"><div class="mini-info"><span>CURRENT LUCK PROFILE</span><strong>Weapon ${luck.weapon.toFixed(0)} · Finish ${luck.skin.toFixed(0)} · Pattern ${luck.pattern.toFixed(0)}</strong></div><div class="mini-info"><span>ROLL ENGINE</span><strong>${state.settings.animations ? 'Animated reveal' : 'Instant reveal'} · CSPRNG</strong></div></div>
          <div class="auto-control" style="margin-top:15px;border-top:1px solid var(--line);padding-top:14px"><div class="row-between"><div><strong style="font-size:10px">AUTO-ROLL</strong><div class="muted" style="font-size:9px;margin-top:3px">${autoActive?'Auto-roll is running.':'Unlock it to roll continuously.'}</div></div><button class="btn ${autoActive?'danger':'cyan-btn'} small" data-action="auto-toggle" ${state.upgrades.autoRoll<=0?'title="Purchase Auto-Roll System first"':''}>${autoActive?'STOP AUTO-ROLL':state.upgrades.autoRoll>0?'START AUTO-ROLL':'LOCKED'}</button></div>
            <div class="auto-stop-row"><select id="autoStopType">${stopOptions.replace(`value="${ui.autoStopType}"`,`value="${ui.autoStopType}" selected`)}</select>${stopValue}<span class="muted">STOP WHEN</span></div>
          </div>
        </div></section>
        <div class="side-stack">
          <section class="panel odds-panel"><div class="panel-head"><div><div class="panel-title">Your luck modifiers</div><div class="panel-sub">Current effective weighting profile</div></div><span class="chip purple">LV ${fmtInt(luck.weapon+luck.skin+luck.pattern)}</span></div>
            <div class="odds-content"><div class="odds-row"><span>Weapon selection</span><strong>LV ${luck.weapon}</strong></div><div class="luck-bar"><div class="luck-fill" style="width:${clamp(luck.weapon*4,3,100)}%"></div></div><div class="odds-row"><span>Skin finish selection</span><strong>LV ${luck.skin}</strong></div><div class="luck-bar"><div class="luck-fill" style="width:${clamp(luck.skin*4,3,100)}%"></div></div><div class="odds-row"><span>Pattern selection</span><strong>LV ${luck.pattern}</strong></div><div class="luck-bar"><div class="luck-fill" style="width:${clamp(luck.pattern*4,3,100)}%"></div></div></div>
            <div class="odds-note">Odds are normalized from rarity weights and recalculate with upgrades and events. Each displayed 1 in X is the effective probability used by the roll engine.</div>
          </section>
          <section class="panel"><div class="panel-head"><div><div class="panel-title">Recent drops</div><div class="panel-sub">Your latest discoveries</div></div><button class="btn ghost small" data-page="inventory">VIEW ALL</button></div><div class="recent-list">${recent.length ? recent.map(r => `<div class="recent-row"><div class="recent-art">${itemArt({ ...r, color:r.color || '#8c91a4' })}</div><div class="recent-copy"><strong>${esc(r.weapon)} · ${esc(r.skin)}</strong><span>${esc(r.pattern || 'N/A')} · ${oddsText(r.odds)}</span></div><span class="recent-price">${money(r.value)}</span></div>`).join('') : `<div class="empty-state" style="padding:25px 10px"><strong>No drops yet</strong><p>Your discoveries will appear here.</p></div>`}</div></section>
        </div>
      </div>
      <div class="below-grid"><section class="panel progress-card"><div class="row-between" style="margin-bottom:14px"><div><div class="panel-title">Collection progress</div><div class="panel-sub">Unique finishes discovered across the full database</div></div><strong class="purple-text">${pct}%</strong></div><div class="progress-track"><span style="width:${pct}%"></span></div><div class="row-between" style="margin-top:10px"><span class="muted" style="font-size:9px">${totalDiscovered} / ${DATA.weapons.reduce((n,w)=>n+w.skins.length,0)} finishes</span><button class="btn ghost small" data-page="collection">OPEN COLLECTION</button></div></section>
      <section class="panel progress-card"><div class="panel-title">Daily objectives</div><div class="panel-sub">Complete goals for bonus cash</div>${state.quests.items.slice(0,2).map(q => `<div class="daily-quest"><div class="quest-symbol">✧</div><div class="quest-copy"><strong>${esc(q.title)}</strong><span>${esc(q.description)} · ${q.progress}/${q.target}</span></div><div class="quest-reward">${q.claimed?'DONE':money(q.reward)}</div></div>`).join('')}</section></div>`;
  }

  function renderInventory() {
    let list = [...state.inventory];
    if (ui.search) list = list.filter(i => `${i.weapon} ${i.skin} ${i.pattern} ${i.category}`.toLowerCase().includes(ui.search.toLowerCase()));
    if (ui.rarity !== 'all') list = list.filter(i => i.tier === ui.rarity);
    if (ui.filter === 'favorites') list = list.filter(i => i.favorite);
    if (ui.filter === 'locked') list = list.filter(i => i.locked);
    if (ui.filter === 'equipped') list = list.filter(i => getEquipped(i.id));
    if (ui.filter === 'knives') list = list.filter(i => i.category === 'Knife');
    if (ui.filter === 'patterns') list = list.filter(i => i.pattern !== 'N/A');
    if (ui.sort === 'value') list.sort((a,b) => currentPrice(b)-currentPrice(a));
    else if (ui.sort === 'odds') list.sort((a,b) => b.combinedOdds-a.combinedOdds);
    else if (ui.sort === 'weapon') list.sort((a,b) => a.weapon.localeCompare(b.weapon));
    else list.sort((a,b) => b.createdAt-a.createdAt);
    const value = list.reduce((sum,i)=>sum+currentPrice(i),0);
    return `${headerHtml('YOUR ARMORY','Inventory','Inspect, protect, equip, and sell your discoveries.',`<span class="chip">${state.inventory.length}/${capacity()} ITEMS</span><span class="chip good">${money(value)} DISPLAYED VALUE</span>`)}
      <div class="toolbar"><div class="search-box"><input id="inventorySearch" type="search" placeholder="Search weapons, finishes, patterns…" value="${esc(ui.search)}"></div><select id="inventoryRarity"><option value="all">All rarities</option>${RARITY_TIERS.map(t=>`<option ${ui.rarity===t.name?'selected':''}>${t.name}</option>`).join('')}</select><select id="inventorySort"><option value="newest" ${ui.sort==='newest'?'selected':''}>Newest first</option><option value="value" ${ui.sort==='value'?'selected':''}>Highest value</option><option value="odds" ${ui.sort==='odds'?'selected':''}>Rarest first</option><option value="weapon" ${ui.sort==='weapon'?'selected':''}>Weapon A–Z</option></select><select id="inventoryFilter"><option value="all" ${ui.filter==='all'?'selected':''}>All items</option><option value="favorites" ${ui.filter==='favorites'?'selected':''}>Favorites</option><option value="locked" ${ui.filter==='locked'?'selected':''}>Locked</option><option value="equipped" ${ui.filter==='equipped'?'selected':''}>Equipped</option><option value="knives" ${ui.filter==='knives'?'selected':''}>Knives</option><option value="patterns" ${ui.filter==='patterns'?'selected':''}>Patterned</option></select><button class="btn small" data-action="select-all">SELECT ALL</button><button class="btn danger small" data-action="bulk-sell">SELL SELECTED (${ui.selected.size})</button></div>
      <div class="row-between" style="margin:0 2px 12px"><span class="toolbar-count">SHOWING ${list.length} OF ${state.inventory.length} ITEMS · LOCKED AND EQUIPPED ITEMS ARE PROTECTED</span><button class="btn ghost small" data-action="clear-selection">CLEAR SELECTION</button></div>
      ${list.length ? `<div class="item-grid">${list.map(i=>itemCard(i,true)).join('')}</div>` : `<div class="panel empty-state"><div class="empty-icon">▦</div><strong>${state.inventory.length?'No matching items':'Your inventory is empty'}</strong><p>${state.inventory.length?'Try changing your search or filters.':'Head to the roll terminal and start discovering weapon finishes.'}</p><button class="btn primary" style="margin-top:14px" data-page="dashboard">GO TO ROLL</button></div>`}`;
  }

  function renderEquipment() {
    const slots = [
      ['primary','Primary weapon','RIFLE'],['secondary','Secondary weapon','PISTOL'],['smg','SMG','SMG'],['knife','Knife','KNIFE'],['gloves','Gloves','GLOVES']
    ];
    const equippedValue = slots.reduce((sum,[slot])=>{const i=state.inventory.find(x=>x.id===state.equipped[slot]);return sum+(i?currentPrice(i):0)},0);
    return `${headerHtml('ACTIVE LOADOUT','Equipment','Equip one item per category to build your passive income engine.',`<span class="chip good">${money(incomePerSecond())} / SEC</span><span class="chip">${money(equippedValue)} EQUIPPED VALUE</span>`)}
      <div class="stat-grid">${statCard('PASSIVE INCOME',money(incomePerSecond())+'/sec','Current live generation','green')}${statCard('EQUIPPED ITEMS',fmtInt(Object.values(state.equipped).filter(Boolean).length),'Maximum 5 equipment slots')}${statCard('INCOME MULTIPLIER',(1+(state.upgrades.incomeBoost||0)*.18).toFixed(2)+'×','From Passive Yield upgrades','purple-text')}${statCard('OFFLINE COLLECTION',Math.min(100,35+(state.upgrades.offlineBoost||0)*6)+'%','Of eligible offline earnings')}</div>
      <div class="slot-grid">${slots.map(([slot,title,type])=>{const item=state.inventory.find(i=>i.id===state.equipped[slot]);return `<div class="slot-card"><div class="slot-top"><strong>${title}</strong><span class="slot-type">${type}</span></div><div class="slot-art">${item?itemArt(item):`<div class="slot-empty">EMPTY SLOT</div>`}</div><div class="slot-foot"><span>${item?money(currentPrice(item))+'/sec value':'NO ITEM'}</span><button class="btn small ${item?'danger':'primary'}" data-action="choose-slot" data-slot="${slot}">${item?'CHANGE':'EQUIP'}</button></div>${item?`<div style="padding:0 11px 10px;font-size:9px;color:var(--green)">+${money(itemIncome(item))}/sec generated</div>`:''}</div>`}).join('')}</div>
      <section class="panel" style="margin-top:16px"><div class="panel-head"><div><div class="panel-title">Income breakdown</div><div class="panel-sub">Each equipped item contributes based on its current market value and combined rarity.</div></div></div><div class="list-panel">${slots.map(([slot,title])=>{const i=state.inventory.find(x=>x.id===state.equipped[slot]);return `<div class="data-row"><div><strong>${title}</strong><small>${i?`${esc(i.weapon)} · ${esc(i.skin)}`:'No item equipped'}</small></div><div>${i?money(itemIncome(i))+'/sec':'—'}</div><div style="text-align:right">${i?`<button class="btn small ghost" data-action="inspect" data-id="${i.id}">INSPECT</button>`:'<span class="muted">Empty</span>'}</div></div>`}).join('')}</div></section>`;
  }
  function itemIncome(item) {
    const rarityFactor = 1 + Math.min(1.8, Math.log10(Math.max(1,item.combinedOdds))*.12);
    return Math.max(.015,Math.sqrt(currentPrice(item))*.012)*rarityFactor*(1+(state.upgrades.incomeBoost||0)*.18)*eventModifiers().income;
  }

  function getEffectiveWeaponOdds(weapon) { return probabilityMap(DATA.weapons, luckLevels().weapon, 'weapon').find(x=>x.entry.id===weapon.id)?.probability || 0; }
  function getEffectiveSkinOdds(weapon, skin) { return probabilityMap(weapon.skins, luckLevels().skin, 'skin').find(x=>x.entry.name===skin.name)?.probability || 0; }
  function getEffectivePatternOdds(skin, pattern) { return skin.patterns ? probabilityMap(skin.patterns, luckLevels().pattern, 'pattern').find(x=>x.entry.name===pattern.name)?.probability || 0 : 1; }
  function renderCollection() {
    const skinTotal = DATA.weapons.reduce((n,w)=>n+w.skins.length,0);
    const patternEntries = DATA.weapons.flatMap(w=>w.skins.flatMap(s=>(s.patterns||[]).map(p=>({w,s,p}))));
    const patternTotal = patternEntries.length;
    const skinFound = Object.keys(state.discoveries.skins).length;
    const patternFound = Object.keys(state.discoveries.patterns).length;
    const rows = ui.collectionTab === 'patterns' ? patternEntries.map(({w,s,p})=>{
      const found = Boolean(state.discoveries.patterns[patternKey(w.id,s.name,p.name)]);
      const odds = (1/getEffectiveWeaponOdds(w))*(1/getEffectiveSkinOdds(w,s))*(1/getEffectivePatternOdds(s,p));
      const baseOdds = (1/(probabilityMap(DATA.weapons,0,'weapon',true).find(x=>x.entry.id===w.id)?.probability||1))*(1/(probabilityMap(w.skins,0,'skin',true).find(x=>x.entry.name===s.name)?.probability||1))*(1/(probabilityMap(s.patterns,0,'pattern',true).find(x=>x.entry.name===p.name)?.probability||1));
      return `<div class="collection-card ${found?'found':''}"><div class="collection-thumb">${itemArt({weapon:w.name,model:w.model,color:s.color,pattern:p.name,id:`${w.id}-${s.name}-${p.name}`})}</div><div class="collection-copy"><strong>${esc(w.name)} · ${esc(s.name)}</strong><span>${esc(p.name)} · BASE ${oddsText(baseOdds)} · NOW ${oddsText(odds)}</span></div><span class="collection-state">${found?'DISCOVERED':'UNKNOWN'}</span></div>`;
    }).join('') : DATA.weapons.flatMap(w=>w.skins.map(s=>{
      const key=itemKey(w.id,s.name); const found=Boolean(state.discoveries.skins[key]);
      const odds=(1/getEffectiveWeaponOdds(w))*(1/getEffectiveSkinOdds(w,s));
      const baseOdds=(1/(probabilityMap(DATA.weapons,0,'weapon',true).find(x=>x.entry.id===w.id)?.probability||1))*(1/(probabilityMap(w.skins,0,'skin',true).find(x=>x.entry.name===s.name)?.probability||1));
      if (ui.collectionFilter==='discovered'&&!found) return '';
      if (ui.collectionFilter==='undiscovered'&&found) return '';
      return `<div class="collection-card ${found?'found':''}"><div class="collection-thumb">${itemArt({weapon:w.name,model:w.model,color:s.color,pattern:'N/A',id:`${w.id}-${s.name}`})}</div><div class="collection-copy"><strong>${esc(w.name)} · ${esc(s.name)}</strong><span>${w.category} · BASE ${oddsText(baseOdds)} · NOW ${oddsText(odds)}${s.patterns?' · PATTERN SKIN':''}</span></div><span class="collection-state">${found?'FOUND':'NOT FOUND'}</span></div>`;
    })).join('');
    const pct = ui.collectionTab==='patterns' ? Math.round(patternFound/Math.max(1,patternTotal)*100) : Math.round(skinFound/Math.max(1,skinTotal)*100);
    return `${headerHtml('THE ARCHIVE','Collection Index','A complete record of every finish and supported pattern in the local database.',`<span class="chip purple">${pct}% COMPLETE</span>`)}
      <div class="stat-grid">${statCard('FINISHES DISCOVERED',`${skinFound}/${skinTotal}`,'Unique weapon and finish combinations')}${statCard('PATTERNS DISCOVERED',`${patternFound}/${patternTotal}`,'Pattern variants tracked separately')}${statCard('WEAPONS FOUND',`${state.stats.weaponsDiscovered}/${DATA.weapons.length}`,'Distinct weapon families')}${statCard('ACHIEVEMENTS',`${state.achievements.length}/${ACHIEVEMENTS.length}`,'Lifetime milestones','gold')}</div>
      <div class="toolbar"><button class="filter-chip ${ui.collectionTab==='skins'?'active':''}" data-action="collection-tab" data-tab="skins">WEAPON FINISHES</button><button class="filter-chip ${ui.collectionTab==='patterns'?'active':''}" data-action="collection-tab" data-tab="patterns">PATTERN VARIANTS</button>${ui.collectionTab==='skins'?`<select id="collectionFilter"><option value="all" ${ui.collectionFilter==='all'?'selected':''}>All finishes</option><option value="discovered" ${ui.collectionFilter==='discovered'?'selected':''}>Discovered</option><option value="undiscovered" ${ui.collectionFilter==='undiscovered'?'selected':''}>Undiscovered</option></select>`:''}<span class="toolbar-count">${ui.collectionTab==='patterns'?patternTotal:skinTotal} DATABASE ENTRIES</span></div>
      <div class="progress-track" style="margin-bottom:14px"><span style="width:${pct}%"></span></div><div class="progress-grid">${rows || `<div class="empty-state panel">No entries in this filter.</div>`}</div>`;
  }

  function renderUpgrades() {
    const groups = ['Luck','Income','Rolling','Inventory'];
    const sections = groups.map(group=>`<div style="margin-bottom:22px"><div class="row-between" style="margin-bottom:11px"><div><div class="section-kicker">${group.toUpperCase()} SYSTEMS</div></div><span class="muted" style="font-size:9px">PERMANENT PROGRESSION</span></div><div class="upgrade-grid">${UPGRADE_DEFS.filter(u=>u.group===group).map(def=>{
      const level=state.upgrades[def.id]||0; const cost=upgradeCost(def); const max=level>=def.max;
      return `<div class="panel upgrade-card"><div class="upgrade-top"><div class="upgrade-icon">${def.icon}</div><div class="upgrade-copy"><strong>${esc(def.title)}</strong><span>${esc(def.group)} upgrade</span></div><div class="upgrade-level">LV ${level}/${def.max}</div></div><div class="upgrade-desc">${esc(def.description)}</div><div class="progress-track"><span style="width:${level/def.max*100}%"></span></div><div class="upgrade-desc" style="margin:8px 0 0;color:#c3b7ea">${esc(def.effect(level))}</div><div class="upgrade-bottom"><span class="upgrade-cost">${max?'MAX LEVEL':money(cost)}</span><button class="btn ${max?'':'primary'} small" data-action="upgrade" data-id="${def.id}" ${max||state.money<cost?'disabled':''}>${max?'MAXED':'UPGRADE'}</button></div></div>`;
    }).join('')}</div></div>`).join('');
    return `${headerHtml('PROGRESSION','Upgrade Lab','Build a stronger roll engine, improve passive income, and unlock automation.',`<span class="chip gold">AVAILABLE ${shortMoney(state.money)}</span>`)}${sections}`;
  }

  function marketCandidates() {
    return DATA.weapons.flatMap(w=>w.skins.map(s=>{
      const wOdds=1/getEffectiveWeaponOdds(w), sOdds=1/getEffectiveSkinOdds(w,s);
      const value=s.value*(1+Math.log10(w.odds+1)*.19)*(1+(state.upgrades.valueBoost||0)*.04);
      return { weapon:w.name, weaponId:w.id, skin:s.name, category:w.category, model:w.model, color:s.color, value:value*state.marketIndex*eventModifiers().market, odds:wOdds*sOdds, pattern:!!s.patterns };
    })).sort((a,b)=>b.value-a.value);
  }
  function renderMarket() {
    const candidates=marketCandidates(); const owned=state.inventory.reduce((n,i)=>n+currentPrice(i),0);
    const history=state.marketHistory.map(x=>x.value);
    return `${headerHtml('SIMULATED EXCHANGE','Market Watch','A local economy model with fluctuating estimates. No real trades or external marketplace connection.',`<span class="chip good">MARKET INDEX ${state.marketIndex.toFixed(3)}×</span>`)}
      <div class="stat-grid">${statCard('MARKET INDEX',state.marketIndex.toFixed(3)+'×','Local simulated price multiplier','purple-text')}${statCard('YOUR INVENTORY VALUE',shortMoney(owned),'Current estimated liquidation value','gold')}${statCard('TOTAL SALES',shortMoney(state.stats.totalSales),'Lifetime sell proceeds')}${statCard('NET CASH FLOW',shortMoney(state.stats.lifetimeEarnings-state.stats.moneySpent),'Earnings minus upgrade and roll spend',state.stats.lifetimeEarnings>=state.stats.moneySpent?'green':'red')}</div>
      <div class="two-col"><section class="panel"><div class="panel-head"><div><div class="panel-title">Market index history</div><div class="panel-sub">Local price movement · new index tick each minute</div></div><span class="chip">LAST ${history.length} TICKS</span></div><div class="chart-wrap"><canvas id="marketChart" class="chart"></canvas></div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Your trading summary</div><div class="panel-sub">Inventory and lifetime sales</div></div></div><div class="list-panel"><div class="data-row"><div>Inventory holdings</div><strong>${state.inventory.length} items</strong><div style="text-align:right">${shortMoney(owned)}</div></div><div class="data-row"><div>Items sold</div><strong>${fmtInt(state.stats.totalSold)}</strong><div style="text-align:right">${shortMoney(state.stats.totalSales)}</div></div><div class="data-row"><div>Money spent</div><strong>${shortMoney(state.stats.moneySpent)}</strong><div style="text-align:right" class="red">OUTFLOW</div></div><div class="data-row"><div>Money earned</div><strong>${shortMoney(state.stats.lifetimeEarnings)}</strong><div style="text-align:right" class="green">INFLOW</div></div></div></section></div>
      <section class="panel" style="margin-top:14px"><div class="panel-head"><div><div class="panel-title">Highest estimated finish values</div><div class="panel-sub">Illustrative database prices · your own item float and pattern affect its value</div></div><span class="chip">SIMULATED PRICING</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>WEAPON / FINISH</th><th>CATEGORY</th><th>BASE ODDS</th><th>EST. VALUE</th><th>TYPE</th></tr></thead><tbody>${candidates.slice(0,20).map(c=>`<tr><td><strong>${esc(c.weapon)}</strong><small style="display:block;color:var(--muted);margin-top:3px">${esc(c.skin)}</small></td><td>${esc(c.category)}</td><td class="mono">${oddsText(c.odds)}</td><td class="mono gold">${money(c.value)}</td><td>${c.pattern?'<span class="purple-text">PATTERN SKIN</span>':'STANDARD'}</td></tr>`).join('')}</tbody></table></div></section>`;
  }

  function renderQuests() {
    return `${headerHtml('DAILY + LIFETIME','Quests & Achievements','Earn cash by rolling, collecting, discovering rare items, and maintaining your loadout.',`<span class="chip good">${state.quests.items.filter(q=>q.claimed).length}/${state.quests.items.length} DAILY CLEARED</span>`)}
      <div class="two-col"><section class="panel"><div class="panel-head"><div><div class="panel-title">Daily objectives</div><div class="panel-sub">Refreshes at the start of each local day</div></div><span class="chip">${esc(state.quests.date)}</span></div><div class="list-panel">${state.quests.items.map(q=>`<div class="daily-quest"><div class="quest-symbol">${q.claimed?'✓':'✧'}</div><div class="quest-copy"><strong>${esc(q.title)}</strong><span>${esc(q.description)}</span><div class="progress-track" style="margin-top:8px"><span style="width:${q.progress/q.target*100}%"></span></div><span>${Math.min(q.progress,q.target)} / ${q.target}</span></div><div class="quest-reward">${q.claimed?'CLAIMED':money(q.reward)}</div></div>`).join('')}</div></section>
      <section class="panel"><div class="panel-head"><div><div class="panel-title">Lifetime milestones</div><div class="panel-sub">Permanent rewards for major discoveries</div></div><span class="chip purple">${state.achievements.length}/${ACHIEVEMENTS.length}</span></div><div class="list-panel">${ACHIEVEMENTS.map(a=>{const done=state.achievements.includes(a.id);return `<div class="daily-quest"><div class="quest-symbol">${done?'✓':'◇'}</div><div class="quest-copy"><strong>${esc(a.title)}</strong><span>${esc(a.desc)}</span></div><div class="quest-reward">${done?'UNLOCKED':money(a.reward)}</div></div>`}).join('')}</div></section></div>`;
  }

  function renderEvents() {
    const active=currentEvent();
    const all=EVENTS.map(event=>`<div class="panel event-card"><div class="event-symbol">${event.icon}</div><span class="chip ${event.id===active.id?'good':''}">${event.id===active.id?'ACTIVE NOW':'ROTATING EVENT'}</span><h3 style="margin-top:11px">${esc(event.name)}</h3><p>${esc(event.description)}</p><div class="event-timer">${esc(event.effect)}${event.id===active.id?' · '+eventTimeLeft():''}</div></div>`).join('');
    return `${headerHtml('LOCAL ROTATION','Live Events','Events rotate locally by day. Bonuses are simulated and affect the real roll and income calculations.',`<span class="chip good">● ACTIVE: ${esc(active.name.toUpperCase())}</span>`)}
      <div class="panel" style="padding:16px;margin-bottom:15px;display:flex;gap:13px;align-items:center"><div class="event-symbol" style="margin:0;flex:0 0 42px">${active.icon}</div><div style="flex:1"><strong style="font-size:12px">${esc(active.name)}</strong><div class="muted" style="font-size:10px;margin-top:4px">${esc(active.description)}</div></div><div class="event-timer">${eventTimeLeft()}</div></div><div class="three-col">${all}</div><p class="muted" style="font-size:9px;margin-top:14px;line-height:1.6">This is a single-player offline rotation. It does not communicate with a global game server, and no event claims to represent other players.</p>`;
  }

  function renderStats() {
    const invValue=state.inventory.reduce((sum,i)=>sum+currentPrice(i),0);
    const best=state.stats.bestDrop || state.inventory.reduce((a,b)=>!a||b.combinedOdds>a.combinedOdds?b:a,null);
    const highest=state.inventory.reduce((a,b)=>!a||currentPrice(b)>currentPrice(a)?b:a,null);
    return `${headerHtml('PERFORMANCE DATA','Statistics','A detailed view of your personal roll history, economy, and collection progress.',`<span class="chip">LOCAL PROFILE</span>`)}
      <div class="stat-grid">${statCard('TOTAL ROLLS',fmtInt(state.stats.totalRolls),'All-time weapon rolls')}${statCard('INVENTORY VALUE',shortMoney(invValue),'Current estimated item value','gold')}${statCard('LIFETIME EARNINGS',shortMoney(state.stats.lifetimeEarnings),'Sales, passive income, rewards','green')}${statCard('MONEY SPENT',shortMoney(state.stats.moneySpent),'Rolls and upgrade purchases','red')}${statCard('WEAPONS DISCOVERED',`${state.stats.weaponsDiscovered}/${DATA.weapons.length}`,'Unique weapon families')}${statCard('FINISHES DISCOVERED',fmtInt(state.stats.skinsDiscovered),'Unique weapon finish combinations')}${statCard('PATTERNS DISCOVERED',fmtInt(state.stats.patternsDiscovered),'Unique special pattern types','purple-text')}${statCard('TOTAL PLAYTIME',formatDuration(state.stats.playSeconds),'Tracked while this game is open')}</div>
      <div class="two-col"><section class="panel"><div class="panel-head"><div><div class="panel-title">Market index movement</div><div class="panel-sub">Local market simulation over recent ticks</div></div></div><div class="chart-wrap"><canvas id="statsMarketChart" class="chart"></canvas></div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Economy overview</div><div class="panel-sub">Tracked income and expenses</div></div></div><div class="chart-wrap"><canvas id="economyChart" class="chart"></canvas></div><div class="list-panel"><div class="data-row"><div>Sales + passive income</div><strong class="green">${shortMoney(state.stats.lifetimeEarnings)}</strong><div></div></div><div class="data-row"><div>Roll + upgrade spending</div><strong class="red">${shortMoney(state.stats.moneySpent)}</strong><div></div></div><div class="data-row"><div>Net tracked flow</div><strong>${shortMoney(state.stats.lifetimeEarnings-state.stats.moneySpent)}</strong><div></div></div></div></section></div>
      <div class="two-col" style="margin-top:14px"><section class="panel"><div class="panel-head"><div><div class="panel-title">Rarest personal drops</div><div class="panel-sub">The rarest combined probability you have recorded</div></div></div><div class="list-panel">${best?`<div class="daily-quest"><div class="quest-symbol">✧</div><div class="quest-copy"><strong>${esc(best.weapon)} · ${esc(best.skin)}</strong><span>${esc(best.pattern)} · ${esc(best.tier)}</span></div><div class="quest-reward">${oddsText(best.combinedOdds)}</div></div>`:'<div class="empty-state">No drops recorded yet.</div>'}</div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Highest value holding</div><div class="panel-sub">Your current most valuable inventory item</div></div></div><div class="list-panel">${highest?`<div class="daily-quest"><div class="recent-art">${itemArt(highest)}</div><div class="quest-copy"><strong>${esc(highest.weapon)} · ${esc(highest.skin)}</strong><span>${esc(highest.wear)} · Float ${highest.float.toFixed(5)}</span></div><div class="quest-reward">${money(currentPrice(highest))}</div></div>`:'<div class="empty-state">No items in inventory.</div>'}</div></section></div>`;
  }
  function formatDuration(seconds) {
    const n=Math.floor(seconds||0); const h=Math.floor(n/3600), m=Math.floor((n%3600)/60);
    return h ? `${h}h ${m}m` : `${m}m`;
  }

  function render() {
    const content=$('#pageContent'); if (!content) return;
    content.innerHTML = ({ dashboard:renderDashboard, inventory:renderInventory, equipment:renderEquipment, collection:renderCollection, upgrades:renderUpgrades, market:renderMarket, quests:renderQuests, events:renderEvents, stats:renderStats }[currentPage] || renderDashboard)();
    $$('#mainNav [data-page]').forEach(btn=>btn.classList.toggle('active',btn.dataset.page===currentPage));
    const pageName=$('#pageName'); if (pageName) pageName.textContent=PAGE_NAMES[currentPage]||'ROLL';
    updateHeader(); drawCharts();
  }

  function drawChart(canvas, values, color = '#9b76ff', secondary = null) {
    if (!canvas) return;
    const rect=canvas.getBoundingClientRect(); const width=Math.max(280,rect.width||500), height=160;
    const dpr=Math.min(window.devicePixelRatio||1,2); canvas.width=width*dpr; canvas.height=height*dpr;
    const ctx=canvas.getContext('2d'); if (!ctx) return; ctx.scale(dpr,dpr); ctx.clearRect(0,0,width,height);
    const pad=16; const min=Math.min(...values, ...(secondary||[])), max=Math.max(...values, ...(secondary||[])); const span=Math.max(.001,max-min);
    ctx.strokeStyle='rgba(190,180,225,.10)'; ctx.lineWidth=1;
    for(let i=0;i<4;i++){const y=pad+(height-pad*2)*i/3;ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(width-pad,y);ctx.stroke();}
    const path=(vals,stroke,fill)=>{if(!vals?.length)return;ctx.beginPath();vals.forEach((v,i)=>{const x=pad+(width-pad*2)*(i/Math.max(1,vals.length-1));const y=height-pad-(v-min)/span*(height-pad*2);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.lineWidth=2;ctx.strokeStyle=stroke;ctx.stroke();if(fill){const xEnd=width-pad;const yBottom=height-pad;ctx.lineTo(xEnd,yBottom);ctx.lineTo(pad,yBottom);ctx.closePath();ctx.fillStyle=fill;ctx.fill();}};
    path(values,color,'rgba(155,118,255,.10)');
    if(secondary)path(secondary,'#42c9e8',null);
  }
  function drawCharts() {
    const values=state.marketHistory.map(x=>x.value); const fallback=[.95,1.02,.97,1.01,1.04,1.0,1.05,1.02];
    requestAnimationFrame(()=>{
      drawChart($('#marketChart'),values.length?values:fallback);
      drawChart($('#statsMarketChart'),values.length?values:fallback);
      const earned=[state.stats.moneySpent,state.stats.totalSales,state.stats.passiveEarned,state.stats.questEarned];
      const canvas=$('#economyChart'); if(canvas){ const rect=canvas.getBoundingClientRect(); const w=Math.max(280,rect.width||500),h=160,dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);c.clearRect(0,0,w,h);const labels=['Spent','Sales','Passive','Quests'];const max=Math.max(1,...earned);earned.forEach((v,i)=>{const bw=(w-50)/4-12;const x=16+i*((w-30)/4);const bh=(h-44)*(v/max);c.fillStyle=i===0?'#e16b7c':i===1?'#55d6a0':i===2?'#42c9e8':'#9b76ff';c.fillRect(x,h-26-bh,bw,bh);c.fillStyle='#8c879f';c.font='9px sans-serif';c.fillText(labels[i],x,h-9);});}
    });
  }

  function openInspect(id) {
    const item=state.inventory.find(i=>i.id===id); if(!item)return;
    ui.inspectId=id;
    const slot=equipmentSlot(item.category); const equipped=getEquipped(id);
    $('#modalRoot').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><div class="modal wide" role="dialog" aria-modal="true" aria-label="Item inspection" onclick="event.stopPropagation()"><div class="modal-head"><div><strong>ITEM INSPECTION</strong><span class="muted" style="font:9px var(--mono);margin-left:10px">${esc(item.tier.toUpperCase())}</span></div><button class="modal-close" data-action="close-modal">×</button></div><div class="modal-body"><div class="inspect-layout"><div><div class="inspect-art">${itemArt(item)}</div><div class="rarity-line" style="--tier-color:${item.tierColor}"></div><div style="display:flex;justify-content:space-between;margin-top:12px"><span class="rarity-tag rarity-${item.tierKey}">${esc(item.tier)}</span><span class="mono gold">${money(currentPrice(item))}</span></div></div><div><div class="inspect-title">${esc(item.weapon)}</div><div class="inspect-finish">${esc(item.skin)}${item.pattern!=='N/A'?` · ${esc(item.pattern)}`:''}</div><div class="detail-grid"><div class="detail-cell"><span>WEAPON ODDS · BASE</span><strong>${oddsText(item.baseWeaponOdds || item.weaponOdds)}</strong></div><div class="detail-cell"><span>WEAPON ODDS · AT DROP</span><strong>${oddsText(item.weaponOdds)}</strong></div><div class="detail-cell"><span>SKIN ODDS · BASE</span><strong>${oddsText(item.baseSkinOdds || item.skinOdds)}</strong></div><div class="detail-cell"><span>SKIN ODDS · AT DROP</span><strong>${oddsText(item.skinOdds)}</strong></div><div class="detail-cell"><span>PATTERN ODDS · BASE</span><strong>${oddsText(item.basePatternOdds || item.patternOdds)}</strong></div><div class="detail-cell"><span>PATTERN ODDS · AT DROP</span><strong>${oddsText(item.patternOdds)}</strong></div><div class="detail-cell"><span>COMBINED · BASE</span><strong>${oddsText(item.baseCombinedOdds || item.combinedOdds)}</strong></div><div class="detail-cell"><span>COMBINED · AT DROP</span><strong>${oddsText(item.combinedOdds)}</strong></div><div class="detail-cell"><span>FLOAT VALUE</span><strong>${item.float.toFixed(6)}</strong></div><div class="detail-cell"><span>WEAR</span><strong>${esc(item.wear)}</strong></div><div class="detail-cell"><span>PATTERN SEED</span><strong>${item.patternSeed??'N/A'}</strong></div><div class="detail-cell"><span>PATTERN MULTIPLIER</span><strong>${item.patternMultiplier?item.patternMultiplier.toFixed(2)+'×':'1.00×'}</strong></div><div class="detail-cell"><span>BASE VALUE</span><strong>${money(item.baseValue)}</strong></div><div class="detail-cell"><span>MARKET VALUE</span><strong>${money(currentPrice(item))}</strong></div></div><div class="btn-row" style="margin-top:15px"><button class="btn ${equipped?'danger':'primary'}" data-action="equip" data-id="${item.id}" ${!slot?'disabled':''}>${equipped?'UNEQUIP':`EQUIP ${slot?.toUpperCase()||''}`}</button><button class="btn" data-action="favorite" data-id="${item.id}">${item.favorite?'★ FAVORITED':'☆ FAVORITE'}</button><button class="btn" data-action="lock" data-id="${item.id}">${item.locked?'UNLOCK':'LOCK ITEM'}</button><button class="btn danger" data-action="sell" data-id="${item.id}" ${item.locked||equipped?'disabled':''}>SELL ${money(currentPrice(item))}</button></div></div></div></div></div></div>`;
  }

  function openSlotPicker(slot) {
    const wanted={primary:'Rifle',secondary:'Pistol',smg:'SMG',knife:'Knife',gloves:'Gloves'}[slot];
    const available=state.inventory.filter(i=>i.category===wanted).sort((a,b)=>currentPrice(b)-currentPrice(a));
    $('#modalRoot').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" onclick="event.stopPropagation()"><div class="modal-head"><strong>SELECT ${slot.toUpperCase()} ITEM</strong><button class="modal-close" data-action="close-modal">×</button></div><div class="modal-body">${available.length?`<div class="item-grid">${available.map(i=>`<div class="item-card" data-action="equip" data-id="${i.id}"><div class="item-card-art">${itemArt(i)}</div><div class="item-card-info"><div class="item-card-name">${esc(i.weapon)} · ${esc(i.skin)}</div><div class="item-card-finish">${esc(i.tier)} · ${oddsText(i.combinedOdds)}</div><div class="item-card-meta"><span class="item-card-value">${money(currentPrice(i))}</span><button class="btn primary small">EQUIP</button></div></div></div>`).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">⌑</div><strong>No ${wanted.toLowerCase()} items found</strong><p>Roll until you discover an item for this slot.</p></div>`}</div></div></div>`;
  }

  function openSettings() {
    $('#modalRoot').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" onclick="event.stopPropagation()"><div class="modal-head"><strong>SETTINGS & SAVE MANAGEMENT</strong><button class="modal-close" data-action="close-modal">×</button></div><div class="modal-body"><div class="settings-grid"><div><div class="section-kicker" style="margin-bottom:9px">DISPLAY & AUDIO</div><label class="switch-row">Enable animations <input type="checkbox" id="settingAnimations" ${state.settings.animations?'checked':''}></label><label class="switch-row">Enable sound effects <input type="checkbox" id="settingSound" ${state.settings.sound?'checked':''}></label><div class="field" style="margin-top:12px"><label>MASTER VOLUME</label><input id="settingVolume" type="range" min="0" max="1" step=".05" value="${state.settings.volume}"></div><div class="muted" style="font-size:9px;line-height:1.5">Sound is generated locally by the browser. No audio files are downloaded.</div></div><div><div class="section-kicker" style="margin-bottom:9px">SAVE DATA</div><p class="muted" style="font-size:9px;line-height:1.6">Your progress is stored in this browser using localStorage and IndexedDB. Export a backup before clearing browser data or moving devices.</p><div class="btn-row" style="margin-top:12px"><button class="btn primary" data-action="export-save">EXPORT SAVE</button><button class="btn" data-action="import-save">IMPORT SAVE</button><input type="file" id="importFile" accept="application/json,.json" hidden></div><div class="muted" style="font-size:8px;margin-top:10px">SAVE VERSION 1 · LAST SAVED ${state.savedAt?new Date(state.savedAt).toLocaleString():'JUST NOW'}</div></div></div><div style="border-top:1px solid var(--line);margin-top:18px;padding-top:15px"><div class="section-kicker">DANGER ZONE</div><p class="muted" style="font-size:9px">Resetting permanently clears this browser's local game save. Export a backup first.</p><button class="btn danger" data-action="reset-save">RESET ALL PROGRESS</button></div></div></div></div>`;
  }

  function showRareAnnouncement(item) {
    autoActive = false;
    const specialPattern = ['Blue Gem','High-Tier Blue Gem','Ruby','Sapphire','Black Pearl','Perfect Full Fade','Fire & Ice'].includes(item.pattern);
    $('#modalRoot').innerHTML = `<div class="modal-backdrop rare-backdrop"><div class="modal rare-modal reveal-${esc(item.tierKey)}" role="dialog" aria-modal="true"><div class="rare-modal-top">${specialPattern ? 'SPECIAL PATTERN DISCOVERED' : 'EXTREMELY RARE DROP'}</div><div class="modal-body rare-modal-body"><div class="rare-stamp">${specialPattern ? esc(item.pattern.toUpperCase()) : esc(item.tier.toUpperCase())}</div><div class="rare-art">${itemArt(item)}</div><h2>${esc(item.weapon)}</h2><div class="rare-finish">${esc(item.skin)}${item.pattern!=='N/A'?` · ${esc(item.pattern)}`:''}</div><div class="rare-odds">${oddsText(item.combinedOdds)}</div><div class="rare-details"><span>FLOAT ${item.float.toFixed(5)}</span><span>SEED ${item.patternSeed ?? 'N/A'}</span><span>VALUE ${money(currentPrice(item))}</span></div><div class="btn-row" style="justify-content:center;margin-top:18px"><button class="btn primary" data-action="inspect-rare" data-id="${esc(item.id)}">INSPECT ITEM</button><button class="btn" data-action="close-modal">CONTINUE</button></div></div></div></div>`;
    toast('Rare drop announcement', `${item.weapon} · ${item.skin} · ${oddsText(item.combinedOdds)}`);
  }

  function navigate(page) {
    if (!PAGE_NAMES[page]) return;
    if (autoActive) { autoActive=false; toast('Auto-roll paused','Navigation changed.'); }
    currentPage=page; ui.selected.clear(); render();
    $('#sidebar')?.classList.remove('open');
    window.scrollTo({top:0,behavior:'smooth'});
  }
  function exportSave() {
    const payload={...state, exportedAt:new Date().toISOString(), app:'DropLab'};
    const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});
    const url=URL.createObjectURL(blob); const a=document.createElement('a');a.href=url;a.download=`droplab-save-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);toast('Save exported','Your JSON backup has been downloaded.');
  }
  async function importSave(file) {
    try {
      const parsed=JSON.parse(await file.text());
      if (!parsed || !Array.isArray(parsed.inventory) || !parsed.stats || !parsed.upgrades) throw new Error('Invalid save structure');
      state=normalizeState(parsed); state.lastTick=Date.now(); refreshDailyQuests(); saveState(); lastDrop=null;ui.selected.clear();closeModal();render();toast('Save imported','Your local game progress has been restored.');
    } catch { toast('Import failed','That file is not a valid DropLab save.'); }
  }
  function closeModal(){ $('#modalRoot').innerHTML=''; ui.inspectId=null; }
  function resetSave(){
    if (!confirm('Reset all DropLab progress in this browser? This cannot be undone unless you exported a backup.')) return;
    state=defaultState();lastDrop=null;autoActive=false;ui.selected.clear();refreshDailyQuests();saveState();closeModal();render();toast('Progress reset','A new local profile has been created.');
  }

  function handleAction(action, target) {
    const id=target.dataset.id;
    switch(action){
      case 'roll': rollBatch(currentRollMode); break;
      case 'roll-mode': currentRollMode=Number(target.dataset.count)||1; render(); break;
      case 'auto-toggle': toggleAutoRoll(); break;
      case 'favorite': { const reopen=Boolean($('#modalRoot .modal')); eventStop(target); toggleFavorite(id); if(reopen)openInspect(id); break; }
      case 'lock': { const reopen=Boolean($('#modalRoot .modal')); eventStop(target); toggleLock(id); if(reopen)openInspect(id); break; }
      case 'inspect': openInspect(id); break;
      case 'inspect-rare': closeModal(); openInspect(id); break;
      case 'sell': eventStop(target); sellItem(id); closeModal(); break;
      case 'equip': eventStop(target); equipItem(id); closeModal(); break;
      case 'choose-slot': openSlotPicker(target.dataset.slot); break;
      case 'upgrade': buyUpgrade(target.dataset.id); break;
      case 'bulk-sell': bulkSell(); break;
      case 'select-all': ui.selected=new Set(state.inventory.filter(i=>!i.locked&&!getEquipped(i.id)).map(i=>i.id)); render(); break;
      case 'clear-selection': ui.selected.clear(); render(); break;
      case 'collection-tab': ui.collectionTab=target.dataset.tab; render(); break;
      case 'settings': openSettings(); break;
      case 'close-modal': closeModal(); break;
      case 'export-save': exportSave(); break;
      case 'import-save': $('#importFile')?.click(); break;
      case 'reset-save': resetSave(); break;
    }
  }
  function eventStop(target){ /* Prevent parent-card actions when a nested button is used. */ target.dataset.stop = '1'; }

  function bindEvents() {
    $('#mainNav').addEventListener('click',e=>{
      const page=e.target.closest('[data-page]'); if(page){navigate(page.dataset.page);return;}
    });
    $('#pageContent').addEventListener('click',e=>{
      const page=e.target.closest('[data-page]'); if(page){navigate(page.dataset.page);return;}
      const actionEl=e.target.closest('[data-action]'); if(!actionEl)return;
      if(actionEl.dataset.action==='select-item')return;
      handleAction(actionEl.dataset.action,actionEl);
    });
    $('#modalRoot').addEventListener('click',e=>{
      const actionEl=e.target.closest('[data-action]'); if(!actionEl)return;
      handleAction(actionEl.dataset.action,actionEl);
    });
    $('#pageContent').addEventListener('change',e=>{
      const el=e.target;
      if(el.id==='inventoryRarity'){ui.rarity=el.value;render();}
      if(el.id==='inventorySort'){ui.sort=el.value;render();}
      if(el.id==='inventoryFilter'){ui.filter=el.value;render();}
      if(el.id==='collectionFilter'){ui.collectionFilter=el.value;render();}
      if(el.id==='autoStopType'){ui.autoStopType=el.value;ui.autoStopValue=el.value==='rarity'?'Legendary':el.value==='weapon'?DATA.weapons[0].id:'1000';render();}
      if(el.id==='autoStopValue'){ui.autoStopValue=el.value;}
      if(el.dataset.action==='select-item'){
        if(el.checked)ui.selected.add(el.dataset.id);else ui.selected.delete(el.dataset.id);
        const count=$('[data-action="bulk-sell"]');if(count)count.textContent=`SELL SELECTED (${ui.selected.size})`;
      }
    });
    $('#pageContent').addEventListener('input',e=>{
      if(e.target.id==='inventorySearch'){ui.search=e.target.value;const pos=e.target.selectionStart;render();const search=$('#inventorySearch');search?.focus();search?.setSelectionRange(pos,pos);}
    });
    $('#modalRoot').addEventListener('change',e=>{
      const el=e.target;
      if(el.id==='settingAnimations'){state.settings.animations=el.checked;saveState();}
      if(el.id==='settingSound'){state.settings.sound=el.checked;saveState();}
      if(el.id==='settingVolume'){state.settings.volume=Number(el.value);saveState();}
      if(el.id==='importFile'&&el.files?.[0])importSave(el.files[0]);
    });
    $('#mobileMenu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
    document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
    window.addEventListener('resize',()=>drawCharts());
  }

  function marketTick() {
    const now=Date.now();
    if (now-state.lastMarketUpdate >= 60000) {
      state.marketIndex=clamp(state.marketIndex*(1+(random()-.48)*.018),.78,1.28);
      state.lastMarketUpdate=now;
      state.marketHistory.push({time:now,value:state.marketIndex});state.marketHistory=state.marketHistory.slice(-40);
      if(currentPage==='market'||currentPage==='stats')render();
    }
  }
  function tick() {
    const now=Date.now(); const elapsed=clamp((now-(state.lastTick||now))/1000,0,5); state.lastTick=now;
    if(elapsed>0){
      const earned=incomePerSecond()*elapsed;
      if(earned>0){state.money+=earned;state.stats.lifetimeEarnings+=earned;state.stats.passiveEarned+=earned;addQuestProgress('earn',earned);}
      state.stats.playSeconds+=elapsed;
      marketTick();updateHeader();
    }
    if(!window.__saveTick){window.__saveTick=0;}
    window.__saveTick+=elapsed;
    if(window.__saveTick>=15){window.__saveTick=0;saveState();}
  }

  async function init() {
    await loadState();
    bindEvents();
    render();
    if(window.__offlineReport?.earned>0){const report=window.__offlineReport;toast('Offline earnings collected',`${money(report.earned)} · ${formatDuration(report.seconds)} away · ${Math.round(report.efficiency*100)}% efficiency.`);}
    if('serviceWorker' in navigator && (location.protocol==='https:'||location.hostname==='localhost')){
      navigator.serviceWorker.register('./sw.js').catch(()=>{});
    }
    setInterval(tick,1000);
    window.addEventListener('beforeunload',saveState);
  }

  init();
})();
